const DB='https://bhfmhzwcogfbnzpdrzih.supabase.co';
const KEY='sb_publishable_POe4-O4LRqn7I-4D_Rz8sw_mxuwHFgp';
const SESSION_KEY='ranisaAdminSession';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allowedImage=value=>/^\/assets\/[a-zA-Z0-9_.-]+$/.test(value||'')||/^https:\/\/bhfmhzwcogfbnzpdrzih\.supabase\.co\/storage\/v1\/object\/public\/ranisa-products\/products\/[a-zA-Z0-9_.-]+$/.test(value||'')?value:'';
const price=value=>value==null?'Price on request':new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(Number(value));
const mediaNames={hero:'Home hero',about:'About us photo',story:'Home story photo',editorial_1:'Editorial photo 1',editorial_2:'Editorial photo 2',editorial_3:'Editorial photo 3',logo:'R logo'};
let session=null,items=[],media=[],editing=null, gallery=[];
function status(id,message,error=false){const el=$(id);el.textContent=message;el.classList.toggle('error',error);}
function show(panel){['authPanel','lockedPanel','dashboard'].forEach(id=>$(id).hidden=id!==panel);}
async function request(path,{method='GET',body,token=session?.access_token,headers={}}={}){
 const response=await fetch(DB+path,{method,headers:{apikey:KEY,...(token?{Authorization:`Bearer ${token}`} :{}),...(body instanceof Blob?{'Content-Type':body.type}:{...(body!==undefined?{'Content-Type':'application/json'}:{})}),...headers},body:body instanceof Blob?body:body===undefined?undefined:JSON.stringify(body)});
 if(!response.ok){let reason='Request failed';try{const data=await response.json();reason=data.msg||data.message||data.error_description||data.error||reason;}catch{}throw new Error(reason);}
 if(response.status===204)return null;
 const text=await response.text();try{return text?JSON.parse(text):null;}catch{return text;}
}
function saveSession(value){session=value;if(value)sessionStorage.setItem(SESSION_KEY,JSON.stringify(value));else sessionStorage.removeItem(SESSION_KEY);}
async function refresh(){if(!session?.refresh_token)throw new Error('Please sign in again.');const next=await request('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:session.refresh_token},token:null});saveSession(next);}
async function privateRequest(path,options={}){if(session?.expires_at&&Date.now()/1000>session.expires_at-45)await refresh();try{return await request(path,options);}catch(error){if(/JWT expired|invalid JWT/i.test(error.message)){await refresh();return request(path,options);}throw error;}}
async function authenticate(){if(!session?.user?.id){show('authPanel');return;}try{const access=await privateRequest(`/rest/v1/ranisa_admin_users?select=user_id&user_id=eq.${encodeURIComponent(session.user.id)}`);if(!access?.length){show('lockedPanel');return;}show('dashboard');await loadDashboard();}catch(error){if(/JWT|session|token|authorized/i.test(error.message)){saveSession(null);show('authPanel');}else{show('lockedPanel');status('authStatus',error.message,true);}}}
async function loadDashboard(){try{[items,media]=await Promise.all([privateRequest('/rest/v1/ranisa_products?select=*&order=sort_order.asc,id.asc'),privateRequest('/rest/v1/ranisa_site_media?select=slot,image_url,alt_text&order=slot.asc')]);renderProducts();renderMedia();}catch(error){status('dashboardStatus',error.message,true);}}
function picture(url,alt){const safe=allowedImage(url);return safe?`<img src="${esc(safe)}" alt="${esc(alt)}">`:'<div class="photo-placeholder">No photo</div>';}
function renderProducts(){$('productList').innerHTML=items.length?items.map(item=>`<article class="admin-row ${item.is_active?'':'inactive'}">${picture(item.image_url,item.name)}<div class="row-info"><strong>${esc(item.name)}</strong><p>${esc(item.category)} · ${price(item.price)} · ${item.is_active?'Visible':'Hidden'} · ${item.gallery_images?.length||0} more photos</p></div><div class="row-actions"><button type="button" class="secondary" data-edit="${item.id}">Edit</button><button type="button" class="danger" data-delete="${item.id}">Delete</button></div></article>`).join(''):'<p>No products yet. Add your first style.</p>';}
function renderMedia(){$('mediaList').innerHTML=media.map(row=>`<article class="admin-row media-row" data-slot="${esc(row.slot)}">${picture(row.image_url,mediaNames[row.slot])}<div class="row-info"><strong>${esc(mediaNames[row.slot]||row.slot)}</strong><small>${row.image_url?'Current photo shown on site':'No photo selected'}</small></div><label class="media-upload">Replace photo<input type="file" accept="image/jpeg,image/png,image/webp" data-media-file="${esc(row.slot)}"></label><button type="button" class="danger" data-remove-media="${esc(row.slot)}" ${row.image_url?'':'disabled'}>Remove</button></article>`).join('');}
function galleryPreview(){ $('galleryPreview').innerHTML=gallery.map((url,index)=>`<div class="gallery-item">${picture(url,'Additional product photo')}<label class="check"><input type="checkbox" data-gallery-remove="${index}"> Remove</label></div>`).join('')||'<p>No additional photos</p>';}
function openProduct(item=null){editing=item;gallery=[...(item?.gallery_images||[])];const form=$('productForm');form.reset();form.elements.name.value=item?.name||'';form.elements.category.value=item?.category||'';form.elements.description.value=item?.description||'';form.elements.price.value=item?.price??'';form.elements.badge.value=item?.badge||'';form.elements.sort_order.value=item?.sort_order??items.length;form.elements.is_active.checked=item?.is_active??true;$('dialogTitle').textContent=item?'Edit product':'Add product';$('coverPreview').innerHTML=picture(item?.image_url,'Product cover');galleryPreview();status('formStatus','');$('productDialog').showModal();}
function validateFile(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Choose a JPEG, PNG or WebP image.');if(file.size>10*1024*1024)throw new Error(`${file.name} is larger than 10 MB.`);}
async function upload(file){validateFile(file);const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type];const object=`products/${crypto.randomUUID()}.${ext}`;await privateRequest(`/storage/v1/object/ranisa-products/${object}`,{method:'POST',body:file});return `${DB}/storage/v1/object/public/ranisa-products/${object}`;}
async function removeObject(url){const prefix=`${DB}/storage/v1/object/public/ranisa-products/`;if(!url?.startsWith(prefix))return;const object=url.slice(prefix.length);if(!/^products\/[a-z0-9-]+\.(jpg|png|webp)$/.test(object))return;try{await privateRequest(`/storage/v1/object/ranisa-products/${object}`,{method:'DELETE'});}catch(error){status('dashboardStatus',`Saved, but an unused photo could not be deleted: ${error.message}`,true);}}
async function removeOrphans(urls){const stillUsed=new Set([...items.flatMap(row=>[row.image_url,...(row.gallery_images||[])]),...media.map(row=>row.image_url)]);await Promise.all(urls.filter(url=>!stillUsed.has(url)).map(removeObject));}
$('authForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const button=$('signIn');button.disabled=true;status('authStatus','Signing in…');try{const result=await request('/auth/v1/token?grant_type=password',{method:'POST',token:null,body:{email:form.elements.email.value.trim(),password:form.elements.password.value}});saveSession(result);status('authStatus','');await authenticate();}catch(error){status('authStatus',error.message,true);}finally{button.disabled=false;}});
async function logout(){try{if(session)await request('/auth/v1/logout',{method:'POST'});}catch{}saveSession(null);show('authPanel');status('authStatus','Signed out.');}
$('logout').onclick=logout;$('lockedLogout').onclick=logout;
document.querySelectorAll('[data-tab]').forEach(tab=>tab.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(t=>t.classList.toggle('selected',t===tab));$('productsPanel').hidden=tab.dataset.tab!=='products';$('mediaPanel').hidden=tab.dataset.tab!=='media';});
$('addProduct').onclick=()=>openProduct();$('closeDialog').onclick=$('cancelDialog').onclick=()=>$('productDialog').close();
$('productList').onclick=async event=>{const edit=event.target.closest('[data-edit]');if(edit){openProduct(items.find(p=>p.id===Number(edit.dataset.edit)));return;}const remove=event.target.closest('[data-delete]');if(!remove)return;const item=items.find(p=>p.id===Number(remove.dataset.delete));if(!item||!confirm(`Permanently delete “${item.name}” from the website?`))return;remove.disabled=true;try{await privateRequest(`/rest/v1/ranisa_products?id=eq.${item.id}`,{method:'DELETE'});items=items.filter(p=>p.id!==item.id);renderProducts();status('dashboardStatus','Product deleted.');await removeOrphans([item.image_url,...(item.gallery_images||[])]);}catch(error){status('dashboardStatus',error.message,true);remove.disabled=false;}};
$('productForm').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget;const save=$('saveProduct');save.disabled=true;status('formStatus','Saving…');const oldUrls=editing?[editing.image_url,...(editing.gallery_images||[])]:[];const uploaded=[];let persisted=false;try{const cover=form.elements.coverFile.files[0],more=[...form.elements.galleryFiles.files];if(cover)validateFile(cover);more.forEach(validateFile);const removed=[...form.querySelectorAll('[data-gallery-remove]:checked')].map(box=>Number(box.dataset.galleryRemove));const keepGallery=gallery.filter((_,index)=>!removed.includes(index));let coverUrl=form.elements.removeCover.checked?'':editing?.image_url||'';if(cover){coverUrl=await upload(cover);uploaded.push(coverUrl);}const newGallery=[];for(const file of more){const url=await upload(file);newGallery.push(url);uploaded.push(url);}const rawPrice=form.elements.price.value.trim();const data={name:form.elements.name.value.trim(),category:form.elements.category.value.trim(),description:form.elements.description.value.trim(),price:rawPrice===''?null:Number(rawPrice),badge:form.elements.badge.value.trim(),sort_order:Number(form.elements.sort_order.value||0),is_active:form.elements.is_active.checked,image_url:coverUrl,gallery_images:[...keepGallery,...newGallery],updated_at:new Date().toISOString()};const path=editing?`/rest/v1/ranisa_products?id=eq.${editing.id}`:'/rest/v1/ranisa_products';await privateRequest(path,{method:editing?'PATCH':'POST',body:data,headers:{Prefer:'return=representation'}});persisted=true;$('productDialog').close();await loadDashboard();status('dashboardStatus','Product saved.');await removeOrphans(oldUrls);}catch(error){status('formStatus',error.message,true);if(!persisted)await Promise.all(uploaded.map(removeObject));}finally{save.disabled=false;}};
$('mediaList').onchange=async event=>{const input=event.target.closest('[data-media-file]');if(!input?.files?.[0])return;const row=media.find(m=>m.slot===input.dataset.mediaFile);const file=input.files[0];let uploaded,persisted=false;try{status('dashboardStatus',`Uploading ${mediaNames[row.slot]}…`);uploaded=await upload(file);await privateRequest(`/rest/v1/ranisa_site_media?slot=eq.${encodeURIComponent(row.slot)}`,{method:'PATCH',body:{image_url:uploaded,updated_at:new Date().toISOString()}});persisted=true;const previous=row.image_url;await loadDashboard();status('dashboardStatus',`${mediaNames[row.slot]} updated.`);await removeOrphans([previous]);}catch(error){status('dashboardStatus',error.message,true);if(uploaded&&!persisted)await removeObject(uploaded);}finally{input.value='';}};
$('mediaList').onclick=async event=>{const button=event.target.closest('[data-remove-media]');if(!button)return;const row=media.find(m=>m.slot===button.dataset.removeMedia);if(!row||!confirm(`Remove ${mediaNames[row.slot]} from the website?`))return;button.disabled=true;try{await privateRequest(`/rest/v1/ranisa_site_media?slot=eq.${encodeURIComponent(row.slot)}`,{method:'PATCH',body:{image_url:'',updated_at:new Date().toISOString()}});await loadDashboard();status('dashboardStatus',`${mediaNames[row.slot]} removed.`);await removeOrphans([row.image_url]);}catch(error){status('dashboardStatus',error.message,true);button.disabled=false;}};

let adminPendingEmail='';
function adminFormatEmail(input){const email=input.trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||email.length>254)throw new Error('Enter a valid email address.');return email;}
$('adminEmailForm').onsubmit=async event=>{event.preventDefault();const button=$('adminSendCode');button.disabled=true;status('authStatus','Sending code…');try{const email=adminFormatEmail($('adminEmail').value);await request('/auth/v1/otp',{method:'POST',token:null,body:{email,create_user:true}});adminPendingEmail=email;$('adminCodeEmail').textContent=email;$('adminEmailForm').hidden=true;$('adminOtpForm').hidden=false;status('authStatus','Check your email for the six-digit code.');}catch(error){status('authStatus',error.message,true);}finally{button.disabled=false;}};
$('adminOtpForm').onsubmit=async event=>{event.preventDefault();const button=$('adminVerifyCode');button.disabled=true;status('authStatus','Verifying…');try{const result=await request('/auth/v1/verify',{method:'POST',token:null,body:{email:adminPendingEmail,token:$('adminCode').value.trim(),type:'email'}});if(!result.user||!result.access_token)throw new Error('The code could not be verified.');saveSession(result);status('authStatus','');await authenticate();}catch(error){status('authStatus',error.message,true);}finally{button.disabled=false;}};
$('adminChangeEmail').onclick=()=>{adminPendingEmail='';$('adminOtpForm').hidden=true;$('adminEmailForm').hidden=false;status('authStatus','');};
try{session=JSON.parse(sessionStorage.getItem(SESSION_KEY)||'null');}catch{saveSession(null);}authenticate();
